import{_ as a,o as r,c as s,ag as t}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"nay_lib","description":"","frontmatter":{},"headers":[],"relativePath":"fr/nay-lib/index.md","filePath":"fr/nay-lib/index.md"}'),i={name:"fr/nay-lib/index.md"};function o(n,e,l,d,u,p){return r(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="nay-lib" tabindex="-1">nay_lib <a class="header-anchor" href="#nay-lib" aria-label="Permalink to &quot;nay_lib&quot;">​</a></h1><p><code>nay_lib</code> est la bibliothèque commune de tous les scripts Nayretis. Vous la recevez avec chaque achat, vous l&#39;installez une fois, et chaque script Nayretis que vous ajoutez l&#39;utilise.</p><h2 id="ce-qu-elle-apporte" tabindex="-1">Ce qu&#39;elle apporte <a class="header-anchor" href="#ce-qu-elle-apporte" aria-label="Permalink to &quot;Ce qu&#39;elle apporte&quot;">​</a></h2><ul><li><strong>Un seul panneau de réglages</strong>, <code>/nay</code>, pour tous les scripts Nayretis. Les réglages sont enregistrés dans votre base et appliqués à tous les joueurs dès l&#39;enregistrement. Voir <a href="/fr/nay-lib/panel">Panneau /nay</a>.</li><li><strong>Des permissions</strong> par ACE ou par identifiant Discord, Steam, FiveM ou license. Voir <a href="/fr/nay-lib/permissions">Permissions</a>.</li><li><strong>Six langues</strong> : anglais, français, espagnol, portugais, polonais et allemand. Une traduction manquante retombe sur l&#39;anglais.</li><li><strong>Un bridge de frameworks</strong> : ESX Legacy, QBCore, QBox et ox_core détectés automatiquement, avec leurs inventaires, targets et notifications. Voir <a href="/fr/bridge/">Bridge</a>.</li><li><strong>Une API HTTP</strong> pour votre site, votre tableau de bord ou votre bot Discord, désactivée par défaut. Voir <a href="/fr/nay-lib/api">API HTTP</a>.</li><li><strong>Des webhooks</strong>, messages Discord compris, pour les événements des scripts. Voir <a href="/fr/nay-lib/webhooks">Webhooks</a>.</li><li><strong>Un journal</strong> de chaque changement fait en jeu, depuis la console ou par l&#39;API. Voir <a href="/fr/nay-lib/audit">Journal</a>.</li><li>Les notifications, invites de touche et barres de progression Nayretis, partagées par tous les scripts.</li></ul><h2 id="prerequis-et-ordre-de-demarrage" tabindex="-1">Prérequis et ordre de démarrage <a class="header-anchor" href="#prerequis-et-ordre-de-demarrage" aria-label="Permalink to &quot;Prérequis et ordre de démarrage&quot;">​</a></h2><p>La seule dépendance est <a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>. Démarrez <code>nay_lib</code> après votre framework, votre inventaire et votre target, et avant tous les scripts Nayretis :</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span></code></pre></div><p>Les tables sont créées au premier démarrage. Les options qui se règlent dans <code>server.cfg</code> sont sur la page <a href="/fr/nay-lib/convars">Convars</a>.</p>`,8)])])}const b=a(i,[["render",o]]);export{g as __pageData,b as default};
